		// 서버 쪽 레이아웃으로 직렬화한다 (테스트의 가짜 서버와 오프라인 데모가 쓴다)
		public byte[] ToBytes()
		{
			PacketWriter w = new PacketWriter((ushort)ZonePacketType.ZcProjectileNotify, Size);
			w.U32(ProjectileId);
			w.U64(CasterId);
			w.U32(SkillId);
			w.U64(TargetId);
			w.F32(X0);
			w.F32(Y0);
			w.F32(X1);
			w.F32(Y1);
			w.U32(FlightMs);
			return w.Finish();
		}
	}

	public sealed class ZcSkillImpactNotify
	{
		public const int Size = 32;
		public uint ProjectileId;
		public ulong CasterId;
		public uint SkillId;
		public float X, Y;
		public uint HitCount;

		public static ZcSkillImpactNotify Parse(byte[] d)
		{
			PacketReader r = new PacketReader(d, ProtocolConst.HeaderSize);
			ZcSkillImpactNotify p = new ZcSkillImpactNotify();
			p.ProjectileId = r.U32();
			p.CasterId = r.U64();
			p.SkillId = r.U32();
			p.X = r.F32();
			p.Y = r.F32();
			p.HitCount = r.U32();
			return p;
		}

		// 서버 쪽 레이아웃으로 직렬화한다 (테스트의 가짜 서버와 오프라인 데모가 쓴다)
		public byte[] ToBytes()
		{
			PacketWriter w = new PacketWriter((ushort)ZonePacketType.ZcSkillImpactNotify, Size);
			w.U32(ProjectileId);
			w.U64(CasterId);
			w.U32(SkillId);
			w.F32(X);
			w.F32(Y);
			w.U32(HitCount);
			return w.Finish();
		}
	}

	public sealed class ZcStatusNotify
	{
		public const int Size = 29;
		public ulong EntityId;
		public uint StatusId;
		public ulong CasterId;
		public uint DurationMs;
		public bool Applied;

		public static ZcStatusNotify Parse(byte[] d)
		{
			PacketReader r = new PacketReader(d, ProtocolConst.HeaderSize);
			ZcStatusNotify p = new ZcStatusNotify();
			p.EntityId = r.U64();
			p.StatusId = r.U32();
			p.CasterId = r.U64();
			p.DurationMs = r.U32();
			p.Applied = r.U8() != 0;
			return p;
		}

		// 서버 쪽 레이아웃으로 직렬화한다 (테스트의 가짜 서버와 오프라인 데모가 쓴다)
		public byte[] ToBytes()
		{
			PacketWriter w = new PacketWriter((ushort)ZonePacketType.ZcStatusNotify, Size);
			w.U64(EntityId);
			w.U32(StatusId);
			w.U64(CasterId);
			w.U32(DurationMs);
			w.U8(Applied ? (byte)1 : (byte)0);
			return w.Finish();
		}
	}
}
